1029	// buildRefundOverflowBackup 构造一个自洽备份：出资账户 payer 的可用余额为
1030	// available，fees 为“策略编号 -> 一笔仍处于已预留状态的请求费用”映射
1031	// （每策略一笔，便于验证跨策略合计）。reserveDur 为这些预留的最长预留
1032	// 时长（零表示关闭超时）；账户/策略的预留总额按 fees 自洽填写。
1033	func buildRefundOverflowBackup(t *testing.T, t0 time.Time, available int64, reserveDur time.Duration, fees map[string]int64) []byte {
1034		t.Helper()
1035		b := backupV1{
1036			Version:    backupVersion,
1037			ExportedAt: timeJSON(t0),
1038			Accounts: []accountBackupV1{
1039				{ID: "payer", Available: available, Reserved: 0, CreatedAt: timeJSON(t0)},
1040				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1041			},
1042			Sessions: []sessionBackupV1{
1043				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(time.Hour)), CreatedAt: timeJSON(t0)},
1044			},
1045			Policies: make([]policyBackupV1, 0, len(fees)),
1046			Requests: make([]requestBackupV1, 0, len(fees)),
1047			Ledger:   []ledgerEntryBackupV1{},
1048		}
1049		var reservedTotal int64
1050		pids := make([]string, 0, len(fees))
1051		for pid := range fees {
1052			pids = append(pids, pid)
1053		}
1054		sort.Strings(pids)
1055		for _, pid := range pids {
1056			fee := fees[pid]
1057			b.Policies = append(b.Policies, policyBackupV1{
1058				ID: pid, PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
1059				Operation: "charge", Payee: "shop",
1060				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(time.Hour)),
1061				MaxPerRequest:      math.MaxInt64,
1062				MaxTotal:           math.MaxInt64,
1063				MaxReserveDuration: durationJSON(reserveDur),
1064				ReservedTotal:      fee,
1065			})
1066			r := requestBackupV1{
1067				PolicyID: pid, RequestID: "req-" + pid, AccountID: "u1", PayerAccountID: "payer",
1068				SessionID: "s1", Operation: "charge", Payee: "shop",
1069				EstimatedFee:    fee,
1070				State:           int(RequestReserved),
1071				CreatedAt:       timeJSON(t0),
1072				ReservedAt:      timeJSON(t0),
1073				ReserveDuration: durationJSON(reserveDur),
1074			}
1075			if reserveDur > 0 {
1076				r.ReserveDeadline = timeJSON(t0.Add(reserveDur))
1077			}
1078			b.Requests = append(b.Requests, r)
1079			sum, ok := addInt64(reservedTotal, fee)
1080			if !ok {
1081				t.Fatalf("test setup reserved total overflow")
1082			}
1083			reservedTotal = sum
1084		}
1085		for i := range b.Accounts {
1086			if b.Accounts[i].ID == "payer" {
1087				b.Accounts[i].Reserved = reservedTotal
1088			}
1089		}
1090		data, err := json.Marshal(&b)
1091		if err != nil {
1092			t.Fatal(err)
1093		}
1094		return data
1095	}
1096	
1097	// TestRestoreRejectsAvailablePlusReservedOverflow 验证可用余额与现存预留
1098	// 合计越过 int64 上限的备份必须被拒绝——即使各请求与策略金额分别合法。
1099	func TestRestoreRejectsAvailablePlusReservedOverflow(t *testing.T) {
1100		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1101	
1102		cases := []struct {
1103			name       string
1104			fees       map[string]int64
1105			available  int64
1106			reserveDur time.Duration
1107			restoreAt  time.Time
1108		}{
1109			{
1110				name:      "max available plus one reserved, not yet due",
1111				fees:      map[string]int64{"p": 1},
1112				available: math.MaxInt64,
1113				restoreAt: t0,
1114			},
1115			{
1116				name:       "max available plus one reserved, due at restore time",
1117				fees:       map[string]int64{"p": 1},
1118				available:  math.MaxInt64,
1119				reserveDur: time.Minute,
1120				restoreAt:  t0.Add(30 * time.Minute),
1121			},
1122			{
1123				name:      "cross-policy reserved sum pushes total over max",
1124				fees:      map[string]int64{"p1": 1, "p2": 1},
1125				available: math.MaxInt64 - 1,
1126				restoreAt: t0,
1127			},
1128		}
1129		for _, tc := range cases {
1130			t.Run(tc.name, func(t *testing.T) {
1131				data := buildRefundOverflowBackup(t, t0, tc.available, tc.reserveDur, tc.fees)
1132				w2, err := restoreAt(data, tc.restoreAt)
1133				if err == nil {
1134					if w2 != nil {
1135						t.Fatalf("overflow backup restored a wallet")
1136					}
1137					t.Fatalf("overflow backup restored without error")
1138				}
1139				if !errors.Is(err, ErrBackupInvalid) {
1140					t.Fatalf("err = %v, want ErrBackupInvalid", err)
1141				}
1142				if msg := err.Error(); !strings.Contains(msg, "payer") || !strings.Contains(msg, "overflows int64") {
1143					t.Fatalf("error %q must name account and the overflow", msg)
1144				}
1145			})
1146		}
1147	}
1148	
1149	// TestRestoreAcceptsAvailablePlusReservedAtBoundary 验证合计恰好等于上限
1150	// 仍然合法：取消或超时退回后可用余额恰好为 MaxInt64；预留为零而可用
1151	// 余额等于上限也能恢复。
1152	func TestRestoreAcceptsAvailablePlusReservedAtBoundary(t *testing.T) {
1153		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1154	
1155		// 可用 = 上限-1，预留 1（未启用超时）：恢复后取消得到上限。
1156		data := buildRefundOverflowBackup(t, t0, math.MaxInt64-1, 0, map[string]int64{"p": 1})
1157		w2, err := restoreAt(data, t0)
1158		if err != nil {
1159			t.Fatalf("boundary restore: %v", err)
1160		}
1161		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 1, Reserved: 1}) {
1162			t.Fatalf("boundary balance = %+v", bal)
1163		}
1164		if _, err := w2.Cancel("u1", "req-p"); err != nil {
1165			t.Fatalf("cancel boundary reservation: %v", err)
1166		}
1167		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
1168			t.Fatalf("balance after cancel = %+v, want available MaxInt64", bal)
1169		}
1170	
1171		// 跨两笔策略的预留合计恰为 2：可用 = 上限-2，逐笔取消后得到上限。
1172		data = buildRefundOverflowBackup(t, t0, math.MaxInt64-2, 0, map[string]int64{"p1": 1, "p2": 1})
1173		w2, err = restoreAt(data, t0)
1174		if err != nil {
1175			t.Fatalf("cross-policy boundary restore: %v", err)
1176		}
1177		for _, rid := range []string{"req-p1", "req-p2"} {
1178			if _, err := w2.Cancel("u1", rid); err != nil {
1179				t.Fatalf("cancel %s: %v", rid, err)
1180			}
1181		}
1182		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
1183			t.Fatalf("balance after cancelling both = %+v, want available MaxInt64", bal)
